19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
23	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.util.CustomerCode.region(owner.getCustomerCode()))")
24	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.util.LuhnCheckDigit.of(owner.getCustomerCode()))")
25	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
26	    @Mapping(target = "membershipLevel", expression = "java(Math.min(3, 1 + ((owner.getEmail() != null && !owner.getEmail().isBlank()) ? 1 : 0) + ((owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) ? 1 : 0)))")
27	    @Mapping(target = "contactPreference", expression = "java((owner.getEmail() != null && !owner.getEmail().isBlank()) ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE)")
28	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.util.OwnerIdentity.identityKey(owner))")
29	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
30	    OwnerDto toOwnerDto(Owner owner);
31	
32	    /**
33	     * Derives the owner's {@code ageBand} from its {@code birthDate}, measured against its
34	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64 and
35	     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date is present.
36	     */
37	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
38	        java.time.LocalDate birthDate = owner.getBirthDate();
39	        java.time.LocalDate asOf = owner.getRegistrationDate();
40	        if (birthDate == null || asOf == null) {
41	            return null;
42	        }
43	        int years = java.time.Period.between(birthDate, asOf).getYears();
44	        if (years < 18) {
45	            return OwnerDto.AgeBandEnum.MINOR;
46	        }
47	        if (years < 65) {
48	            return OwnerDto.AgeBandEnum.ADULT;
49	        }
50	        return OwnerDto.AgeBandEnum.SENIOR;
51	    }
52	
53	    Owner toOwner(OwnerDto ownerDto);
54	
55	    @Mapping(target = "id", ignore = true)
56	    @Mapping(target = "pets", ignore = true)
57	    Owner toOwner(OwnerFieldsDto ownerDto);
58	
59	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
60	
61	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
62	
63	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
64	        OwnerPageDto ownerPageDto = new OwnerPageDto();
65	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
66	        ownerPageDto.setPage(ownerPage.getNumber());
67	        ownerPageDto.setSize(ownerPage.getSize());
68	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
69	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
70	        return ownerPageDto;
71	    }
